import { Component } from '@angular/core';
import { LightboxFor } from 'ng-gallery/lightbox';
import { LightboxModule } from 'ng-gallery/lightbox';

@Component({
  selector: 'app-demo',
  imports: [LightboxFor, LightboxModule],
  template: `
    <ng-template lightbox #lightbox="lightbox" panelClass="g-glass-theme">
        <gallery [items]="items" gap="48">
            <img
                *galleryItemDef="let item"
                galleryImage
                [src]="item.src"
                [alt]="item.alt"
                [style.object-fit]="'cover'" />
            <gallery-nav/>
            <gallery-counter/>
        </gallery>
    </ng-template>
    <div class="grid">
        @for (item of items; track i; let i = $index) {
        <div
            class="grid-item"
            [lightboxFor]="lightbox"
            [lightboxIndex]="i">
            <img class="grid-image" loading="lazy" [src]="item.thumb"/>
        </div>
        }
    </div>`,
})
export class DemoComponent {}
